// them, rendered through the single shared ServiceDetailPage component).
// Mirrors lib/servicePageContent.js and lib/industryPageContent.js: real,
// already-live copy transcribed once here (extracted directly from each
// page.js's own hardcoded props/consts, so it's byte-exact) so
// lib/subServiceContentRegistry.js can generate dashboard defaults from it
// and each app/(main)/<hub>/<slug>/page.js can merge dashboard overrides on
// top of it, instead of two sources of truth drifting apart.
//
// Icons, the serviceBreakdown "number"/"ctaText" constants, and the
// differentiators/roadmap "number" constants are intentionally kept here
// (needed so page.js can still render them) but are NOT exposed as
// dashboard-editable fields in subServiceContentRegistry.js — same rule
// every other content registry in this codebase follows.
