    localityHeading: "Based in Prayagraj, Advising Businesses Worldwide",
    localityText: "BizzBuzz Creations is based in Prayagraj, Uttar Pradesh, and that local grounding shapes how we approach every strategy engagement, with the same rigor whether a client is nearby or overseas. We work with startups, SMBs, and enterprises across India, building strategy sized to each business's actual goals and market position. For businesses looking to work with us beyond India, we deliver strategy consulting remotely, working across time zones to the same standard regardless of location. Whether you're a founder clarifying your first roadmap or an enterprise aligning multiple business units, our approach starts with the same question: what does your business actually need this strategy to achieve.",
    localityImage: "/Business Strategy Consulting 2.png",

    faqs: [
      { question: "How much does business strategy consulting cost in India?", answer: "Cost depends on scope, a focused strategic review costs less than a comprehensive corporate strategy engagement with execution support. We scope pricing after understanding your specific situation and goals, rather than offering a flat rate upfront." },
      { question: "What's the difference between a strategy consultant and a business coach?", answer: "A strategy consultant typically focuses on analyzing your market and business to develop a specific strategic plan, while a business coach often focuses more broadly on leadership development and ongoing guidance. We combine strategic analysis with practical, ongoing support." },
      { question: "How long does a typical strategy consulting engagement take?", answer: "Timeline depends on scope, a focused strategic review can take a few weeks, while a comprehensive strategy with execution support typically continues over several months. We provide a specific timeline after understanding your situation." },
      { question: "Do you help with execution, or just the strategy document itself?", answer: "We help with both, since a strategy that never gets executed provides little value. We build execution support directly into our engagements, staying involved as your team implements the plan." },
      { question: "Can strategy consulting help a business that's already struggling?", answer: "Yes, strategy consulting is often especially valuable for businesses facing real challenges, since an objective outside view can identify issues and opportunities that internal teams under pressure may not see clearly." },
      { question: "Do you work with small businesses, or only larger companies?", answer: "We work with businesses of various sizes, scoping our approach to fit smaller businesses just as thoughtfully as larger corporate engagements, rather than offering a one-size-fits-all consulting package." },
    ],

    ctaHeading: "Ready for a Strategy You Can Actually Execute?",
