// Keyed by "<hub>-<slug>" rather than slug alone: one slug
// ("generative-engine-optimization") is reused by two different pages
// under two different hubs (search-engine-optimization and ai-solutions),
// so slug alone isn't a safe unique key across all 44 pages.
export function getSubServicePageContent(hub, slug) {
  return SUB_SERVICE_PAGE_CONTENT[`${hub}-${slug}`];
}
